-  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
+  // U10f: past the low window the legs see RAM at the high base -- QEMU
+  // places the backend there itself (DRAM_ALIAS + DRAM_EXT are contiguous),
+  // vsim gets it as --shared-mem-base. "0x0" for every legacy size.
+  {
+    char base_hex[32];
