--- a/driver/shm.cpp
+++ b/driver/shm.cpp
@@ -91,3 +91,12 @@ long long max_program_mem_bytes() {
-  // AE350 DRAM window is 2 GiB; leave room for the scratch page on top.
-  constexpr long long kAe350DramWindowBytes = 2LL * 1024 * 1024 * 1024;
-  return kAe350DramWindowBytes - HYBRID_V_SCRATCH_BYTES;
+  // U10f: the contiguous high view -- DRAM alias (2G) + DRAM_EXT (14G) from
+  // 0x8_00000000 -- with the scratch page on top. At or below the low window
+  // the flat-from-zero map is kept (hybrid_ram_base decides which).
+  constexpr long long kAe350RamWindowsBytes = 16LL * 1024 * 1024 * 1024;
+  return kAe350RamWindowsBytes - HYBRID_V_SCRATCH_BYTES;
+}
+
+uint64_t hybrid_ram_base(long long mem_bytes) {
+  // Keep the historical flat-from-zero map while program + scratch fit the
+  // low window: every cycle number recorded there stays comparable.
+  const long long low_window = 2LL * 1024 * 1024 * 1024;
+  return physical_mmap_bytes(mem_bytes) <= low_window ? 0u : 0x800000000ull;
@@ -135,0 +145,17 @@ std::vector<std::string> qemu_m_args(const std::string& spec,
+std::string fast_linux_mem_error(const std::string& spec) {
+  if (spec.empty()) return "";
+  std::string err;
+  const long long bytes = parse_size(spec, err);
+  if (!err.empty()) return "";  // malformed: qemu_m_args reports it
+  const long long ceiling = 16LL * 1024 * 1024 * 1024;
+  if (bytes <= ceiling) return "";
+  return "--mem-size " + spec +
+         " exceeds what --runtime linux can address (max 16G, the AE350 "
+         "DRAM + DRAM_EXT windows; hybrid mode has its own 2G cap)";
+}
+
+uint64_t fast_linux_ram_base(long long mem_bytes) {
+  const long long low_window = 2LL * 1024 * 1024 * 1024;
+  return mem_bytes <= low_window ? 0u : 0x800000000ull;
+}
+
diff --git a/driver/shm.hpp b/driver/shm.hpp
index a0e9858..a6d7371 100644
--- a/driver/shm.hpp
+++ b/driver/shm.hpp
@@ -10,0 +11 @@
+#include <cstdint>
@@ -51,0 +53,23 @@ long long max_program_mem_bytes();
+// U10b/U10e: ceiling check for `--mode fast --runtime linux`. With ram_base
+// support the guest addresses the contiguous high view -- DRAM alias (2 GiB)
+// + DRAM_EXT (14 GiB) from 0x8_00000000 -- so the ceiling is 16 GiB (QEMU
+// AE350 refuses more anyway, but failing here beats staging first). Returns
+// "" when `spec` is empty (the 1G default applies later), malformed
+// (qemu_m_args owns that error), or within the window; otherwise a
+// ready-to-print message. Hybrid mode keeps its own separate 2 GiB cap.
+std::string fast_linux_mem_error(const std::string& spec);
+
+// U10e: the guest RAM base fast+linux hands vlinux for a given --mem-size.
+// At or below 2 GiB the historical flat-from-zero map is kept so every
+// known-good run stays byte-identical; above it RAM must live in the high
+// window, where DRAM_ALIAS + DRAM_EXT are contiguous from 0x8_00000000.
+uint64_t fast_linux_ram_base(long long mem_bytes);
+
+// U10f: the guest RAM base hybrid hands vlinux AND the legs (QEMU backend
+// placement, vsim --shared-mem-base) for a given --mem-size. While program +
+// V-scratch page fit the low 2 GiB window the flat-from-zero map is kept, so
+// every recorded cycle number stays comparable; past it RAM moves to
+// 0x8_00000000 (needs a BIU >= 36-bit engine; ax46mpv_fpga_l3 is 39 since
+// 2026-07-29).
+uint64_t hybrid_ram_base(long long mem_bytes);
+

